using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestMethod]
    [DataRow("5551234567")]
    [DataRow("8005551234")]
    public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens(string digits)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.StartsWith($"({digits[..3]})", result);
    }

    [TestMethod]
    [DataRow("5551234567", "4567")]
    [DataRow("8005551234", "1234")]
    public void FormatPhoneNumber_ValidDigits_EndsWithLastFour(string digits, string lastFour)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.EndsWith(lastFour, result);
    }

    [TestMethod]
    public void FormatPhoneNumber_ValidDigits_ContainsDash()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        Assert.Contains("-", result);
    }

    [TestMethod]
    public void FormatPhoneNumber_ValidDigits_ReturnsCorrectFormat()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        Assert.AreEqual("(555) 123-4567", result);
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
        Assert.AreEqual("digits", ex.ParamName);
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    public void FormatPhoneNumber_WrongLength_ThrowsArgumentException(string digits)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
    }

    [TestMethod]
    [DataRow("Alice", "Mr.", "Dear Mr. Alice,")]
    [DataRow("Bob", "Dr.", "Dear Dr. Bob,")]
    public void BuildGreeting_WithTitle_StartsWithDear(string name, string title, string expected)
    {
        var result = _formatter.BuildGreeting(name, title);

        Assert.StartsWith("Dear", result);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    [DataRow("Alice")]
    [DataRow("Bob")]
    public void BuildGreeting_AnyName_EndsWithComma(string name)
    {
        var result = _formatter.BuildGreeting(name);

        Assert.EndsWith(",", result);
    }

    [TestMethod]
    public void BuildGreeting_WithName_ContainsName()
    {
        var result = _formatter.BuildGreeting("Alice");

        Assert.Contains("Alice", result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_NullOrWhiteSpace_Throws(string? name)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name!));
    }

    [TestMethod]
    [DataRow("Hello World", "hello-world")]
    [DataRow("  My Blog Post!  ", "my-blog-post")]
    [DataRow("C# is GREAT", "c-is-great")]
    public void GenerateSlug_ValidTitle_ReturnsExpected(string title, string expected)
    {
        var result = _formatter.GenerateSlug(title);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void GenerateSlug_ValidTitle_MatchesSlugPattern()
    {
        var result = _formatter.GenerateSlug("Hello World!!!");

        Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
    }

    [TestMethod]
    public void GenerateSlug_NullOrWhiteSpace_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(""));
    }

    [TestMethod]
    [DataRow("$", "19.99")]
    [DataRow("€", "19.99")]
    public void FormatCurrency_WithSymbol_StartsWithSymbol(string symbol, string amount)
    {
        var result = _formatter.FormatCurrency(decimal.Parse(amount), symbol);

        Assert.StartsWith(symbol, result);
    }

    [TestMethod]
    public void FormatCurrency_WholeNumber_EndsWithTwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(5m);

        Assert.EndsWith(".00", result);
    }

    [TestMethod]
    [DataRow(19.99, "$19.99")]
    [DataRow(0.5, "$0.50")]
    [DataRow(1000, "$1000.00")]
    public void FormatCurrency_DefaultSymbol_ReturnsExpected(double amount, string expected)
    {
        var result = _formatter.FormatCurrency((decimal)amount);

        Assert.AreEqual(expected, result);
    }
}

